def build_agent(sandbox):
    # Agent is already present, return the agent's body
    agent = sandbox.get_agent_body()
    return agent

def agent_action(sandbox, agent_body, step_count):
    next_sw = sandbox.get_next_required_switch()
    if next_sw is None:
        return  # Task complete

    pos = sandbox.get_agent_position()
    steps_in_zone = sandbox.get_steps_in_current_zone()
    steps_required = sandbox.get_steps_required_to_trigger()
    cooldown = sandbox.get_cooldown_remaining()
    barrier_delay = sandbox.get_barrier_delay_steps()
    barrier_x = sandbox.get_barrier_x()

    # Determine target zone based on next_sw
    target_pos = None
    if next_sw == 'A':
        target_pos = (2.0, 2.0)
    elif next_sw == 'B':
        target_pos = (4.95, 3.2)
    elif next_sw == 'C':
        target_pos = (8.0, 2.0)

    # Check if in the target zone
    in_zone = False
    if next_sw == 'A':
        in_zone = (1.5 <= pos[0] <= 2.5) and (1.5 <= pos[1] <= 2.5)
    elif next_sw == 'B':
        in_zone = (4.25 <= pos[0] <= 5.65) and (2.8 <= pos[1] <= 3.6)
    elif next_sw == 'C':
        in_zone = (7.5 <= pos[0] <= 8.5) and (1.5 <= pos[1] <= 2.5)

    # Calculate direction to target
    dx = target_pos[0] - pos[0]
    dy = target_pos[1] - pos[1]
    dist = math.hypot(dx, dy)
    force_x = 0.0
    force_y = 0.0
    if dist > 0:
        dir_x = dx / dist
        dir_y = dy / dist
        force_x = dir_x * 0.03
        force_y = dir_y * 0.03

    # Handle A
