        if not in_zone:
            # Move towards A
            sandbox.apply_agent_force(force_x, force_y)
        else:
            if steps_in_zone < steps_required:
                # Apply zero force
                pass
            else:
                # A triggered, check barrier delay
                if barrier_delay > 0:
                    # Wait for barrier to open
                    pass
                else:
                    # Barrier is open, move towards B
                    sandbox.apply_agent_force(force_x, force_y)
    elif next_sw == 'B':
